import React from 'react';

import { omitTransientProps } from 'utils/emotion';

import type { ChipIconProps } from '../../Chip.types';
import { StyledChipIcon } from './ChipIcon.styles';

export const ChipIcon = React.forwardRef<HTMLDivElement, ChipIconProps>(
  ({ icon: Icon, className, ...props }, forwardedRef) => (
    <StyledChipIcon
      {...omitTransientProps(props)}
      ref={forwardedRef}
      className={className}
      tabIndex={-1}
    >
      <Icon />
    </StyledChipIcon>
  ),
);

ChipIcon.displayName = 'Chip.Icon';
